import type { ProviderBBatch, ProviderBStorage, Reservation, Service, ServiceResponse, Stock } from "./types";
import { error, parseReservationCommand, reservationResponse } from "./reservation";
import {
  decodeProviderBReservationRow,
  decodeProviderBStockRow,
  encodeDecimal,
  isRecord,
  isRevision,
  providerBReservationToReservation,
  providerBStockToStock,
} from "./validation";

type Lookup<T> =
  | Readonly<{ kind: "found"; value: T }>
  | Readonly<{ kind: "missing" }>
  | Readonly<{ kind: "unavailable" }>;

function decodeReadEnvelope<T>(raw: unknown, decodeValue: (value: unknown) => T | undefined): Lookup<T> {
  if (!isRecord(raw) || typeof raw.ok !== "boolean") return { kind: "unavailable" };
  if (raw.ok) {
    const value = decodeValue(raw.value);
    return value === undefined ? { kind: "unavailable" } : { kind: "found", value };
  }
  if (!isRecord(raw.error) || typeof raw.error.reason !== "string") return { kind: "unavailable" };
  if (raw.error.reason === "NO_SUCH_KEY") return { kind: "missing" };
  return { kind: "unavailable" };
}

async function readStock(storage: ProviderBStorage, sku: string): Promise<Lookup<Stock>> {
  const envelope = await storage.read({ collection: "inventory", key: sku });
  return decodeReadEnvelope(envelope, (value) => {
    const row = decodeProviderBStockRow(value);
    if (row === undefined || row.itemKey !== sku) return undefined;
    return providerBStockToStock(row);
  });
}

async function readReservation(storage: ProviderBStorage, reservationId: string): Promise<Lookup<Reservation>> {
  const envelope = await storage.read({ collection: "reservations", key: reservationId });
  return decodeReadEnvelope(envelope, (value) => {
    const row = decodeProviderBReservationRow(value);
    if (row === undefined || row.bookingKey !== reservationId) return undefined;
    return providerBReservationToReservation(row);
  });
}

function reservationBatch(stock: Stock, reservation: Reservation): ProviderBBatch | undefined {
  const nextRevision = stock.revision + 1;
  if (!isRevision(nextRevision)) return undefined;
  const nextReservedUnits = stock.reservedUnits + reservation.quantity;
  return {
    expectedRevisionText: encodeDecimal(stock.revision),
    stockRow: {
      itemKey: stock.sku,
      onHandText: encodeDecimal(stock.totalUnits),
      heldText: encodeDecimal(nextReservedUnits),
      revisionText: encodeDecimal(nextRevision),
    },
    reservationRow: {
      bookingKey: reservation.reservationId,
      itemKey: reservation.sku,
      unitsText: encodeDecimal(reservation.quantity),
    },
    outboxRows: [{
      key: "reservation.created:" + reservation.reservationId,
      category: "reservation",
      name: "created",
      payload: {
        bookingKey: reservation.reservationId,
        itemKey: reservation.sku,
        unitsText: encodeDecimal(reservation.quantity),
      },
    }],
  };
}

export function createProviderBReservationService({ storage }: { storage: ProviderBStorage }): Service {
  return {
    async handle(raw): Promise<ServiceResponse> {
      const command = parseReservationCommand(raw);
      if (command === undefined) return error(400, "invalid_command");
      try {
        if (command.op === "getAvailability") {
          const stock = await readStock(storage, command.sku);
          if (stock.kind === "missing") return error(404, "stock_not_found");
          if (stock.kind === "unavailable") return error(500, "storage_unavailable");
          return {
            status: 200,
            body: {
              sku: stock.value.sku,
              totalUnits: stock.value.totalUnits,
              reservedUnits: stock.value.reservedUnits,
              availableUnits: stock.value.totalUnits - stock.value.reservedUnits,
            },
          };
        }

        const existing = await readReservation(storage, command.reservationId);
        if (existing.kind === "unavailable") return error(500, "storage_unavailable");
        if (command.op === "getReservation") {
          return existing.kind === "found"
            ? reservationResponse(200, existing.value)
            : error(404, "reservation_not_found");
        }
        if (existing.kind === "found") {
          return existing.value.sku === command.sku && existing.value.quantity === command.quantity
            ? reservationResponse(200, existing.value)
            : error(409, "reservation_conflict");
        }

        const stock = await readStock(storage, command.sku);
        if (stock.kind === "missing") return error(404, "stock_not_found");
        if (stock.kind === "unavailable") return error(500, "storage_unavailable");
        if (stock.value.totalUnits - stock.value.reservedUnits < command.quantity) {
          return error(409, "insufficient_stock");
        }
        const reservation: Reservation = {
          reservationId: command.reservationId,
          sku: command.sku,
          quantity: command.quantity,
        };
        const batch = reservationBatch(stock.value, reservation);
        if (batch === undefined) return error(500, "storage_unavailable");
        const outcome = await storage.commitBatch(batch);
        if (outcome === "revision_conflict") return error(409, "commit_conflict");
        if (outcome !== "applied") return error(500, "storage_unavailable");
        return reservationResponse(201, reservation);
      } catch {
        return error(500, "storage_unavailable");
      }
    },
  };
}

