export type Stock = {
  sku: string;
  totalUnits: number;
  reservedUnits: number;
  revision: number;
};

export type Reservation = {
  reservationId: string;
  sku: string;
  quantity: number;
};

export type ReservationEvent = {
  eventId: string;
  type: "reservation.created";
  reservationId: string;
  sku: string;
  quantity: number;
};

export type ReservationCommit = {
  expectedRevision: number;
  nextStock: Stock;
  reservation: Reservation;
  events: ReservationEvent[];
};

export type LegacyStorage = {
  getStock(sku: string): Promise<unknown>;
  getReservation(reservationId: string): Promise<unknown>;
  commitReservation(change: ReservationCommit): Promise<unknown>;
};

export type ProviderBReadRequest = Readonly<{
  collection: "inventory" | "reservations";
  key: string;
}>;

export type ProviderBStockRow = Readonly<{
  itemKey: string;
  onHandText: string;
  heldText: string;
  revisionText: string;
}>;

export type ProviderBReservationRow = Readonly<{
  bookingKey: string;
  itemKey: string;
  unitsText: string;
}>;

export type ProviderBOutboxRow = Readonly<{
  key: string;
  category: "reservation";
  name: "created";
  payload: Readonly<{
    bookingKey: string;
    itemKey: string;
    unitsText: string;
  }>;
}>;

export type ProviderBBatch = Readonly<{
  expectedRevisionText: string;
  stockRow: ProviderBStockRow;
  reservationRow: ProviderBReservationRow;
  outboxRows: ReadonlyArray<ProviderBOutboxRow>;
}>;

export type ProviderBStorage = Readonly<{
  read: (request: ProviderBReadRequest) => Promise<unknown>;
  commitBatch: (batch: ProviderBBatch) => Promise<unknown>;
}>;

export type SnapshotRow = Readonly<{
  sku: string;
  totalUnits: number;
  reservedUnits: number;
}>;

export type StockReportSource = Readonly<{
  readSnapshot: () => Promise<unknown>;
}>;

export type ObservationEvent = Readonly<{
  type: "inventory.observed";
  observationId: string;
  sku: string;
  observedUnits: number;
}>;

export type ObservationSink = Readonly<{
  appendObservation: (event: ObservationEvent) => Promise<unknown>;
}>;

export type ServiceResponse = {
  status: 200 | 201 | 400 | 404 | 409 | 500;
  body: Record<string, unknown>;
};

export type Service = {
  handle(command: unknown): Promise<ServiceResponse>;
};

